NAME = 'ACV: A Conservative Version'
BOOK = 'Lamentations'

CHAPTERS = {
    1: {
        1: 'Kako samotno je ostalo mesto, ki je bilo polno ljudstva! Vdovi je podobno – prej oblastno med narodi, kneginja med pokrajinami, sedaj plačuje davek!',
        2: 'Joka in joka po noči in solze ji teko po licih; nihče je ne tolaži izmed vseh ljubiteljev njenih; vsi prijatelji njeni so se ji izneverili, postali so ji sovražniki.',
        3: 'Juda je šel v pregnanstvo zaradi stiske in velike sužnosti: prebiva med pogani, pokoja ni našel; vsi preganjalci njegovi so ga dohiteli v tesnobi.',
        4: 'Pota na Sion žalujejo, ker nihče ne pride na praznovanje; vsa vrata njena so zapuščena, duhovniki njeni zdihujejo; device njene so žalostne in sama je v bridkosti.',
        5: 'Zatiralci njeni so ji postali glava, sovražniki njeni živé mirno; kajti Gospod jo je užalil zavoljo obilosti pregreh njenih; otročiči njeni gredo v sužnost vpričo zatiralca.',
        6: 'In hčer sionsko je minila vsa krasota njena; njeni knezi so kakor jeleni, ki ne najdejo paše, in onemogli so odšli preganjalcu pred očmi.',
        7: 'V dneh stiske svoje in tavanja svojega se spominja Jeruzalem vseh svojih dragotin, ki jih je imel od starih dni, ker je ljudstvo njegovo padlo po roki zatiralčevi in mu nihče ni prišel na pomoč. Zatiralci ga vidijo, posmehujejo se njegovi pogubi.',
        8: 'Hudo je grešila Jeruzalem, zato je kakor zavoljo nesnage ločena; vsi, ki so jo častili, jo zaničujejo, ker so videli nagoto njeno; tudi sama zdihuje in se ozira za seboj.',
        9: 'Nesnaga njena je na robu obleke njene; ni se spominjala konca svojega, zato je čudovito prišla na nič; nihče je ne tolaži. Ozri se, Gospod, v ponižanje moje, zakaj poveličal se je sovražnik!',
        10: 'Roko svojo je iztegnil zatiralec po vseh dragotinah njenih; kajti videla je, kako so šli v svetišče njeno pogani, o katerih si zapovedal, da ne smejo stopiti v zbor tvoj!',
        11: 'Vse ljudstvo njeno zdihuje in išče kruha; svoje dragotine dajó za jed, da se požive. Ozri se, Gospod, in glej, kako me zaničujejo!',
        12: 'Nič vam mari, vi vsi, ki greste mimo po poti? Glejte in vidite, je li bolečina enaka bolečini moji, ki so jo storili meni, ki me je Gospod napolnil z bridkostjo v dan goreče jeze svoje!',
        13: 'Z višave je poslal ogenj v kosti moje in jih je premagal; mrežo je razpel nogam mojim, pognal me je nazaj; naredil me je opustošeno in hirajočo ves dan.',
        14: 'Steknila je jarem pregreh mojih roka njegova: spletene so, spenjajo se čez vrat moj – uničena je moč moja. Gospod me je dal v pesti, iz katerih se ne morem iztrgati.',
        15: 'Poteptal je Gospod vse junake moje sredi mene; zoper mene je sklical prazničen shod, da potare mladeniče moje. Gospod je teptal kakor v tlačilnici devico, hčer Judovo.',
        16: 'Zato jokam, iz oči mojih teče voda navzdol, ker je daleč od mene tolažnik, ki bi mi poživil dušo; otroci moji so izgubljeni, ker je prevladal sovražnik.',
        17: 'Roke svoje izteza hči sionska: nikogar ni, ki bi jo tolažil. Zapovedal je Gospod o Jakobu, naj ga obstopijo zatiralci njegovi; kakor ženska, zavoljo nesnage ločena, je Jeruzalem med njimi.',
        18: 'Pravičen je Gospod, zato ker sem bila nepokorna ustom njegovim. Poslušajte, prosim, vsa ljudstva, in poglejte bolečino mojo! Device moje in mladeniči moji so šli v sužnost.',
        19: 'Klicala sem ljubitelje svoje, a oni so me obnorili; duhovniki in starejšine moji so izdehnili dušo v mestu, ko so si iskali jedi, da bi se poživili ž njo.',
        20: 'Poglej, o Gospod, kajti v stiski sem, v osrčju mojem kipi bridkost, premetava se srce moje v meni, ker sem se grozno uprla. Zunaj mi mori otroke meč, doma je kakor smrt.',
        21: 'Slišali so, da zdihujem: nihče me ne tolaži; vsi sovražniki moji so slišali za nesrečo mojo, veselili so se, da si to storil. Ko pripelješ dan, ki si ga napovedal, tedaj mi bodo enaki.',
        22: 'Pred obličje tvoje pridi vsa njih hudobnost in stóri jim, kakor si storil meni zavoljo vseh prestopkov mojih; kajti preobili so zdihljaji moji in srce moje hira silno.',
    },
    2: {
        1: 'Kako je pokril Gospod z gostim oblakom hčer sionsko v jezi svoji! Iz nebes na zemljo je vrgel diko Izraelovo in ni se spomnil podnožja nog svojih v jeze svoje dan!',
        2: 'Podrl je Gospod neusmiljeno vsa prebivališča Jakobova, v srdu svojem je porušil trdnjave hčere Judove; na tla je zvrnil, kakor oskrunjeno je zavrgel kraljestvo s knezi njegovimi.',
        3: 'V srditi jezi je zdrobil vsak rog Izraelov; umaknil je desnico svojo, ko je prišel sovražnik, in požgal je Jakoba kakor ogenj plameneč, ki vse požira.',
        4: 'Lok svoj je napel kako sovražnik, postavil se je z desnico svojo kakor nasprotnik in pomoril je vse, kar je bilo očem drago; v šatoru hčere sionske je izlil kakor ogenj togoto svojo.',
        5: 'Ravnal je Gospod kakor sovražnik: pokončal je Izraela, pokončal vse gradove njegove, razdrl vse trdnjave njegove, in mnogo je prizadel hčeri Judovi žalosti in jadikovanja.',
        6: 'In s silo je podrl kočo svojo kakor plot na vrtu, porušil je kraj shoda svojega; Gospod je storil, da se je pozabilo praznično zborovanje in sobota na Sionu, in v nevolji jeze svoje je zavrgel kralja in duhovnika.',
        7: 'Gospod je zavrgel oltar svoj, zastudil je svetišče svoje, v roko sovražnikovo je dal zidove njenih palač: hrumeli so v hiši Gospodovi, kakor da je prazničnega shoda dan.',
        8: 'Gospod je sklenil razvaliti zidove hčere sionske: potegnil je mersko vrv, ni umaknil roke svoje, da bi ne pokončal; in žalovanje je pripravil nasipu in zidu, oboje žalostno leži skupaj.',
        9: 'V zemljo so se pogreznila vrata njena, polomil in zdrobil je zapahe njene; kralj njen in knezi njeni so med poganskimi narodi, kjer ni postave, tudi proroki njeni ne prejemajo več prikazni od Gospoda.',
        10: 'Na tleh sede molče starejšine hčere sionske; s pepelom so si potresli glave, prepasali se z raševnikom; na tla povešajo glavo device jeruzalemske.',
        11: 'Od solzá mi pešajo oči, v osrčju mi kipi bridkost, na zemljo se usipljejo jetra moja zavoljo potrtja hčere ljudstva mojega, ko otročiči in dojenci koprne po mestnih ulicah.',
        12: 'Materam svojim govore: Kje je žito in vino? ko omedlevajo kakor smrtno ranjeni po ulicah mestnih, ko se njih duša izliva materam v naročje.',
        13: 'Kaj naj ti izpričam, kak zgled naj ti dam, o hči jeruzalemska? Kaj naj primerjam tebi, da te potolažim, o devica, hči sionska? Kajti veliko je kakor morje potrtje tvoje, kdo te more ozdraviti?',
        14: 'Proroki tvoji so ti videli prikazni prazne in neslane ter niso odkrivali krivičnosti tvoje, da bi bili odvrnili preselitev tvojo v sužnost; ali videli so zate praznih reči bremena [T. j. prorokovanja.] in takih, zaradi katerih si morala biti odgnana.',
        15: 'Z rokami ploskajo nad teboj vsi, ki gredo mimo po potu, žvižgajo in majejo z glavami proti hčeri jeruzalemski, češ: Je li to tisto mesto, katero so imenovali Dovršenost lepote, Veselje vse zemlje?',
        16: 'Zoper tebe širijo usta vsi sovražniki tvoji, žvižgajo in škripljejo z zobmi, pravijo: Požrli smo jo! res, to je tisti dan, ki smo ga pričakovali, zdaj ga imamo in vidimo!',
        17: 'Gospod je storil, kar je sklenil, izpolnil je govor svoj, ki ga je sporočil od starodavnih dni. Rušil je brez milosti in sovražniku je dal veseliti se nad teboj, povzdignil je rog neprijateljev tvojih.',
        18: 'Srce jim vpije h Gospodu. O zid hčere sionske, stóri, da teko solze kakor reka po dnevi in po noči; ne dovoli si prestanka, ne počivaj punčica očesa tvojega!',
        19: 'Vstani, vpij po noči, ob začetku straž, izlivaj kakor vode srce svoje pred obličjem Gospodovim, povzdiguj k njemu roke svoje za dušo otročičev svojih, ki koprne od glada po vseh ulicah in voglih.',
        20: 'Ozri se, o Gospod, in glej, komu delaš tako! Ali bodo žene jedle sad svoj, otročiče, ki jih nosijo v naročju? V svetišču Gospodovem ali naj moré duhovnika in proroka?',
        21: 'Na tleh leže po ulicah dečki in starčki; device moje in mladeniči moji so padli od meča, pomoril si jih v dan jeze svoje, poklal brez milosti.',
        22: 'Sklical si kakor na dan prazničnega shoda strašila moja od vseh strani, in ni ga bilo, ki bi bil ubežal ali ostal živ v dan jeze Gospodove; nje, ki sem jih nosila v naročju in vzredila, je pokončal sovražnik moj.',
    },
    3: {
        1: 'Jaz sem tisti mož, ki okuša bridkost po šibi togote njegove.',
        2: 'Mene vodi in goni po temi, ne pa po svetlobi.',
        3: 'Samo meni nasprotujoč, obrača proti meni roko svojo ves dan.',
        4: 'Storil je, da se je postaralo meso moje in koža moja, kosti moje je potrl.',
        5: 'Zidal je zoper mene in me obdal s strupeno grenkobo in nadlogo.',
        6: 'Velel mi je bivati v temnih krajih, kakor tisti, ki so mrtvi za vselej.',
        7: 'Ogradil me je, da ne morem uiti, dejal me je v težko železje.',
        8: 'Ko tudi kličem in vpijem, ne pusti k sebi prošnje moje.',
        9: 'Pota moja je zagradil z rezanim kamenjem, steze mi je izprevrgel.',
        10: 'Kakor prežeč medved mi je, kakor lev v zasedi.',
        11: 'Pota moja je napravil tavajoča in me je raztrgal, me opustošil.',
        12: 'Napel je lok svoj in me je postavil pšici svoji za cilj.',
        13: 'V ledice moje je izpustil tula svojega strelice.',
        14: 'V smeh sem vsemu ljudstvu svojemu, njih pesmica ves dan.',
        15: 'Nasitil me je z najhujšo bridkostjo, upijanil me je s pelinom.',
        16: 'In s kamenjem mi je zdrobil zobe, povalil me je v pepel.',
        17: 'In vržena je daleč od miru duša moja, pozabil sem, kar je sreča.',
        18: 'In rekel sem: Izginila je moč moja in moje upanje v Gospoda.',
        19: 'Spomni se edinščine moje in tavanja mojega, pelina in grenkega strupa!',
        20: 'Spominja se tega vedno duša moja in je potrta v meni.',
        21: 'To si hočem vtisniti v srce, zato bom upal:',
        22: 'Prevelika dobrotljivost Gospodova je, da nismo docela pokončani, ker nima konca usmiljenje njegovo,',
        23: 'novo je vsako jutro; preobila je zvestoba tvoja.',
        24: 'Delež moj je Gospod, govori duša moja, zato bom upal vanj.',
        25: 'Dober je Gospod njim, ki ga čakajo, duši, ki ga išče.',
        26: 'Dobro je možu, da upa in tiho čaka rešitve Gospodove.',
        27: 'Dobro je možu, da je nosil jarem v mladosti svoji.',
        28: 'Samoten naj sedi in molči, ker mu ga je naložil Gospod.',
        29: 'V prah naj položi usta: morda je še upanje.',
        30: 'Njemu, ki ga bije, naj pomoli lice svoje; nasiti se naj s sramoto.',
        31: 'Kajti Gospod ne zameta vekomaj;',
        32: 'marveč, ko je užalostil, se tudi usmili po obilosti dobrot svojih.',
        33: 'Nikakor ne muči iz srca, ne žali otrok človeških.',
        34: 'Če kdo gazi vse zvezane na zemlji,',
        35: 'če zavija pravico možu pred obličjem Najvišjega,',
        36: 'če prekanja človeka v pravdi njegovi: ne bo li Gospod pazil na to?',
        37: 'Kdo je, ki je velel, in se je zgodilo, če ni tega zapovedal Gospod?',
        38: 'Ali ne prihaja iz ust Najvišjega hudo in dobro?',
        39: 'Kaj bi tožil človek, dokler živi? Vsakdo naj toži zaradi svojih grehov!',
        40: 'Preiskujmo ter izsledujmo pota svoja in vrnimo se do Gospoda!',
        41: 'Povzdignimo dušo svojo z rokami vred k Bogu mogočnemu v nebesih!',
        42: 'Mi, mi smo se pregrešili in se uprli; ti nisi odpustil.',
        43: 'Ogrnil si se z jezo in preganjal nas, moril si brez milosti.',
        44: 'Z oblakom si se ogrnil, da ne predere molitev.',
        45: 'Za nesnago in izmeček si nas postavil sredi ljudstev.',
        46: 'Vsi sovražniki naši so usta svoja razširili zoper nas.',
        47: 'Groza in jama sta blizu nas, razdejanje in poguba.',
        48: 'Potoke vodá toči oko moje zavoljo pogube hčere mojega ljudstva.',
        49: 'Oko moje se solzi in ne neha, ni nobenega prestanka,',
        50: 'dokler se Gospod iz nebes ne ozre in ne vidi.',
        51: 'Oko moje mi žali srce zavoljo vseh hčer mesta mojega.',
        52: 'Lovili so me hudo kakor ptičico, kateri me sovražijo brez vzroka.',
        53: 'V jamo so pehnili življenje moje, da me uničijo, in kamenje so lučali v me.',
        54: 'Vode so mi kipele čez glavo, dejal sem: Pokončan sem!',
        55: 'Klical sem ime tvoje, o Gospod, iz jame pregloboke.',
        56: 'Glas moj si čul; ne skrivaj ušesa svojega zdihovanju mojemu, vpitju mojemu.',
        57: 'Približal si se tisti dan, ko sem klical; rekel si: Ne boj se!',
        58: 'Sodil si, Gospod, pravdo duše moje, odrešil si življenje moje.',
        59: 'Videl si, o Gospod, krivico, ki se mi godi; razsodi pravdo mojo!',
        60: 'Videl si vse njih maščevanje in vse njih naklepe zoper mene.',
        61: 'Slišal si njih zasramovanje, o Gospod, in vse njih namere zoper mene,',
        62: 'govorjenje tistih, ki so vstali nadme, in njih izmišljevanje zoper mene ves dan.',
        63: 'Glej jih, ko sede in ko vstajajo, da jim sem za pesmico!',
        64: 'Plačaj jim povračilo, Gospod, po njih rok delu.',
        65: 'Daj jim zaslepljenost srca, prokletje tvoje pridi nadnje!',
        66: 'Preganjaj jih v jezi in zatri jih izpod nebes Gospodovih!',
    },
    4: {
        1: 'Kako je otemnelo zlato, se izpremenilo odlično zlato! Kako je raztreseno kamenje svetišča po vseh voglih in ulicah!',
        2: 'Sinovi Siona, predragi, ki bi jih bilo ceniti z zlatom najčistejšim, kako se čislajo za vrče prstene, za izdelek rok lončarjevih!',
        3: 'Celo šakali ponujajo prsi, dojé mladiče svoje, ali ljudstva mojega hči je neusmiljena kakor noji v puščavi!',
        4: 'Jezik lepí dojenčku na nebesu od žeje; otročiči prosijo kruha, a ni ga, da bi ga delil.',
        5: 'Oni, ki so jedli slaščice, premirajo po ulicah; oni, ki so bili vzrejeni v škrlatu, objemajo blato.',
        6: 'In hujša je krivda ljudstva mojega hčere nego krivda Sodome, ki je bila podrta nagloma, roke se niso utrudile ž njo.',
        7: 'Čistejši nego sneg so bili knezi njeni, bolj beli nego mleko, bolj rdeči po životu nego korale, gladki kakor safir.',
        8: 'Temnejša od črnine je sedaj njih podoba, ne poznajo jih na ulicah; njih koža se je zrasla ž njih kostmi, suha je kakor les.',
        9: 'Bolje je pomorjenim z mečem nego pomorjenim z lakoto, ker ti umirajo prebodeni s stradanjem, ker ni poljskega sadú.',
        10: 'Roke žen usmiljenih so kuhale otroke svoje, za hrano so jim bili ob razdejanju hčere ljudstva mojega.',
        11: 'Gospod je dopolnil togoto svojo, srdito jezo svojo je izlil in ogenj zažgal na Sionu, ki je požrl podstave njegove.',
        12: 'Ne bi bili verjeli kralji zemeljski in vsi prebivalci vesoljnega sveta, da pride zatiralec in sovražnik v vrata jeruzalemska.',
        13: 'Zgodilo se je zavoljo grehov prorokov njegovih, krivic duhovnikov njegovih, ki so prelivali sredi njega kri pravičnih.',
        14: 'Kakor slepci so tavali po ulicah, ognušeni so bili s krvjo, da se niso hoteli ljudje dotekniti njih oblačil.',
        15: '„Umeknite se, nečisti!“so vpili proti njim, „umeknite se, umeknite, ne doteknite se!“Ko so bežali, so tudi tavali, in med narodi se je govorilo: Ne smejo več pri nas prebivati!',
        16: 'Srdito obličje Gospodovo jih je razkropilo, ne bo jih gledal več. Na duhovnike se niso ozirali, starčkom niso prizanašali.',
        17: 'Še nam oči hirajo v hrepenenju po prazni pomoči; z ogledovalnice svoje gledamo proti narodu, ki ne bo rešil.',
        18: 'Lové stopinje naše, da ne moremo hoditi po ulicah svojih. Bliža se konec naš, dovršujejo se dnevi naši, da, konec naš je že prišel.',
        19: 'Hitrejši so bili naši preganjalci nego orli pod nebom: po gorah so nas podili, v puščavi so nas zalezovali.',
        20: 'Dih življenja našega, maziljenec Gospodov, je bil ujet v njih jamah; o katerem smo rekli: V senci njegovi bomo živeli med narodi.',
        21: 'Veséli in raduj se, o hči Edomova, prebivalka v deželi Uzovi! Tudi k tebi pride čaša, upijaniš se in slečeš se do nagega.',
        22: 'Končana je kazen krivde tvoje, o hči sionska! ne bo te več vodil v pregnanstvo. Ozre se v krivico tvojo, o hči Edomova, odkrije grehe tvoje.',
    },
    5: {
        1: 'Spomni se, o Gospod, kaj nas je zadelo, ozri se in poglej sramoto našo!',
        2: 'Dediščina naša je pripadla tujcem, hiše naše inozemcem.',
        3: 'Sirote smo, brez očeta, matere naše so kakor vdove.',
        4: 'Vode svoje pijemo za denar, drva svoja dobivamo za plačilo.',
        5: 'Preganjalci naši nam stopajo na vrat; utrujeni smo, ne dovolijo nam pokoja.',
        6: 'Egipčanu molimo roko, tudi Asircu, da se nasitimo kruha.',
        7: 'Očetje naši so grešili, in ni jih več; nam pa je nositi njih krivice.',
        8: 'Hlapci nam gospodujejo; nikogar ni, ki bi nas oprostil iz njih roke.',
        9: 'Z nevarnostjo življenja svojega prinašamo kruh svoj spričo meča puščave.',
        10: 'Koža naša je začrnela kakor peč zavoljo vroče lakote.',
        11: 'Žene na Sionu so oskrunjali, device po mestih Judovih.',
        12: 'Poglavarje obešajo njih roke, starčkov obličje se ne časti.',
        13: 'Mladeniči nosijo mlinske kamene in dečki padajo pod lesom.',
        14: 'Starci so nehali shajati se med vrati, mladeniči na petje svoje.',
        15: 'Minilo je srca našega veselje, v žalost se je preobrnil naš ples.',
        16: 'Venec naše glave je padel. Gorje nam! ker smo grešili.',
        17: 'Zato omedleva srce naše, zavoljo tega so nam otemnele oči:',
        18: 'zavoljo gore Sionske, ki je opustošena; lisice prosto hodijo po njej.',
        19: 'Ti, Gospod, ostaneš vekomaj, prestol tvoj od roda do roda.',
        20: 'Zakaj nas vekomaj pozabljaš, hočeš li nas zapustiti za dolge čase?',
        21: 'Pelji nas nazaj k sebi, o Gospod, da se povrnemo; ponovi dni naše kakor v prejšnjih časih!',
        22: 'Ali bi nas popolnoma zavrgel, razsrdil se zoper nas tako silno?',
    },
}
